1	//! Blocking test harness over the engine contract.
2	//!
3	//! Integration tests predate the step-batched wire protocol and want the old
4	//! per-request stream ergonomics; this pump restores them the same way the
5	//! production bridge does — one thread demultiplexes `StepOutputs` into
6	//! per-request queues. Everything here is synchronous: GPU tests drive
7	//! requests from plain test threads.
8	
9	// Each integration test crate compiles this module independently and uses a
10	// different slice of it.
11	#![allow(dead_code)]
12	
13	use std::collections::HashMap;
14	use std::collections::VecDeque;
15	use std::sync::Arc;
16	use std::sync::Condvar;
17	use std::sync::Mutex;
18	
19	use pegainfer_frontend::engine::Engine;
20	use pegainfer_frontend::engine::EngineInfo;
21	use pegainfer_frontend::engine::EosPolicy;
22	use pegainfer_frontend::engine::LoraClient;
23	use pegainfer_frontend::engine::PromptEcho;
24	use pegainfer_frontend::engine::Request;
25	use pegainfer_frontend::engine::RequestControl;
26	use pegainfer_frontend::engine::RequestId;
27	use pegainfer_frontend::engine::RequestUpdate;
28	use pegainfer_frontend::engine::SchedulerHandle;
29	use pegainfer_frontend::engine::SchedulerMetrics;
30	use pegainfer_frontend::engine::StopPolicy;
31	use pegainfer_frontend::engine::Terminal;
32	use pegainfer_frontend::engine::TokenLogprob;
33	use pegainfer_frontend::sampler::SamplingParams;
34	
35	/// A contract request with test defaults; adjust fields on the result for
36	/// prompt-logprob/completion-logprob/LoRA variants.
37	pub(crate) fn request(
38	    prompt_tokens: Vec<u32>,
39	    params: SamplingParams,
40	    max_tokens: usize,
41	) -> Request {
42	    let stop_policy = StopPolicy::new(
43	        if params.ignore_eos {
44	            EosPolicy::Ignore
45	        } else {
46	            EosPolicy::ModelDefault
47	        },
48	        Vec::new(),
49	    );
50	
51	    Request {
52	        prompt_tokens,
53	        params,
54	        history_tokens: None,
55	        history_marks: Vec::new(),
56	        stop_policy,
57	        max_tokens,
58	        lora_adapter: None,
59	        kv_transfer_params: None,
60	        logprobs: None,
61	        prompt_logprobs: None,
62	        trace_parent: None,
63	        client_label: None,
64	    }
65	}
66	
67	pub(crate) struct EngineHarness {
68	    handle: Option<SchedulerHandle>,
69	    lora: Option<LoraClient>,
70	    scheduler_join: Option<std::thread::JoinHandle<()>>,
71	    pump_join: Option<std::thread::JoinHandle<()>>,
72	    inbox: Arc<Inbox>,
73	    pub(crate) info: EngineInfo,
74	}
75	
76	struct Inbox {
77	    state: Mutex<InboxState>,
78	    cv: Condvar,
79	}
80	
81	struct InboxState {
82	    updates: HashMap<RequestId, VecDeque<RequestUpdate>>,
83	    closed: bool,
84	}
85	
86	impl EngineHarness {
87	    pub(crate) fn new(mut engine: Engine) -> Self {
88	        assert_eq!(
89	            engine.schedulers.len(),
90	            1,
91	            "test harness drives single-scheduler engines"
92	        );
93	        let mut scheduler = engine.schedulers.remove(0);
94	        let mut steps = scheduler
95	            .handle
96	            .take_steps()
97	            .expect("a fresh scheduler yields its step stream once");
98	        let inbox = Arc::new(Inbox {
99	            state: Mutex::new(InboxState {
100	                updates: HashMap::new(),
101	                closed: false,
102	            }),
103	            cv: Condvar::new(),
104	        });
105	        let pump_inbox = Arc::clone(&inbox);
106	        let pump_join = std::thread::spawn(move || {
107	            while let Some(step) = steps.blocking_recv() {
108	                let mut state = pump_inbox.state.lock().unwrap();
109	                for update in step.updates {
110	                    state
111	                        .updates
112	                        .entry(update.id)
113	                        .or_default()
114	                        .push_back(update);
115	                }
116	                drop(state);
117	                pump_inbox.cv.notify_all();
118	            }
119	            pump_inbox.state.lock().unwrap().closed = true;
120	            pump_inbox.cv.notify_all();
121	        });
122	        Self {
123	            handle: Some(scheduler.handle),
124	            lora: engine.lora,
125	            scheduler_join: Some(scheduler.join),
126	            pump_join: Some(pump_join),
127	            inbox,
128	            info: engine.info,
129	        }
130	    }
131	
132	    pub(crate) fn submit(&self, request: Request) -> RequestStream {
133	        let control = self
134	            .handle
135	            .as_ref()
136	            .expect("harness handle lives until drop")
137	            .submit(request);
138	        RequestStream {
139	            id: control.id(),
140	            control,
141	            inbox: Arc::clone(&self.inbox),
142	        }
143	    }
144	
145	    pub(crate) fn metrics(&self) -> SchedulerMetrics {
146	        self.handle
147	            .as_ref()
148	            .expect("harness handle lives until drop")
149	            .metrics()
150	    }
151	
152	    /// The engine's LoRA client; panics when the engine serves no adapter
153	    /// control — the `Option` on `Engine::lora` is the capability.
154	    pub(crate) fn lora_client(&self) -> LoraClient {
155	        self.lora.clone().expect("engine exposes LoRA control")
156	    }
157	
158	    /// Submit one request and return its generated token ids, panicking on any
159	    /// non-`Finished` terminal — the shape most GPU tests want.
160	    pub(crate) fn generate(
161	        &self,
162	        prompt_tokens: Vec<u32>,
163	        params: SamplingParams,
164	        max_tokens: usize,
165	    ) -> Vec<u32> {
166	        self.submit(request(prompt_tokens, params, max_tokens))
167	            .expect_finished()
168	            .tokens
169	    }
170	}
171	
172	impl Drop for EngineHarness {
173	    fn drop(&mut self) {
174	        // Closing the submission channel lets the scheduler drain and exit;
175	        // the step stream then closes and the pump follows.
176	        drop(self.handle.take());
177	        if let Some(join) = self.scheduler_join.take() {
178	            let _ = join.join();
179	        }
180	        if let Some(join) = self.pump_join.take() {
181	            let _ = join.join();
182	        }
183	    }
184	}
185	
186	/// One request's demultiplexed view of the step stream. `Send`, so tests may
187	/// drive concurrent requests from separate threads.
188	pub(crate) struct RequestStream {
189	    id: RequestId,
190	    pub(crate) control: RequestControl,
191	    inbox: Arc<Inbox>,
192	}
193	
194	impl RequestStream {
195	    pub(crate) fn id(&self) -> RequestId {
196	        self.id
197	    }
198	
199	    /// Next update for this request; `None` once the engine is gone.
200	    pub(crate) fn recv(&mut self) -> Option<RequestUpdate> {
201	        let mut state = self.inbox.state.lock().unwrap();
202	        loop {
203	            if let Some(update) = state
204	                .updates
205	                .get_mut(&self.id)
206	                .and_then(VecDeque::pop_front)
207	            {
208	                return Some(update);
209	            }
210	            if state.closed {
211	                return None;
212	            }
213	            state = self.inbox.cv.wait(state).unwrap();
214	        }
215	    }
216	
217	    /// Fold the stream to its terminal. Panics if the engine dies first — a
218	    /// vanished stream is a test failure, not an outcome.
219	    pub(crate) fn outcome(mut self) -> Outcome {
220	        let mut outcome = Outcome {
221	            tokens: Vec::new(),
222	            logprobs: Vec::new(),
223	            cached_tokens: None,
224	            prompt_echo: None,
225	            terminal: Terminal::Failed {
226	                message: String::new(),
227	                prompt_tokens: 0,
228	                completion_tokens: 0,
229	            },
230	        };
231	        loop {
232	            let update = self
233	                .recv()
234	                .expect("engine closed the stream without a terminal");
235	            outcome.tokens.extend_from_slice(&update.tokens);
236	            outcome.logprobs.extend(update.logprobs);
237	            if update.cached_tokens.is_some() {
238	                assert!(
239	                    outcome.cached_tokens.is_none(),
240	                    "cached_tokens must be reported at most once per request"
241	                );
242	                outcome.cached_tokens = update.cached_tokens;
243	            }
244	            if update.prompt_echo.is_some() {
245	                outcome.prompt_echo = update.prompt_echo;
246	            }
247	            if let Some(terminal) = update.terminal {
248	                outcome.terminal = terminal;
249	                return outcome;
250	            }
251	        }
252	    }
253	
254	    /// The common success path: fold to the terminal and require `Finished`.
255	    pub(crate) fn expect_finished(self) -> Outcome {
256	        let outcome = self.outcome();
257	        match &outcome.terminal {
258	            Terminal::Finished { .. } => outcome,
259	            Terminal::Rejected { reason, .. } => panic!("generation rejected: {reason}"),
260	            Terminal::Failed { message, .. } => panic!("generation failed: {message}"),
261	        }
262	    }
263	}
264	
265	/// A finished request, folded: everything the old per-request event stream
266	/// delivered incrementally.
267	pub(crate) struct Outcome {
268	    pub(crate) tokens: Vec<u32>,
269	    pub(crate) logprobs: Vec<Option<TokenLogprob>>,
270	    pub(crate) cached_tokens: Option<usize>,
271	    pub(crate) prompt_echo: Option<PromptEcho>,
272	    pub(crate) terminal: Terminal,
273	}
274	
275	/// Minimal stderr logger for gate children (`PEGAINFER_TEST_LOG=1`): the
276	/// hedged execution gate counts the executor's per-round hedge trace lines,
277	/// and cargo test binaries install no logger of their own. Forwarding only
278	/// this crate's records keeps child stderr parseable.
279	struct TestLogger;
280	
281	impl log::Log for TestLogger {
282	    fn enabled(&self, metadata: &log::Metadata) -> bool {
283	        metadata.target().starts_with("pegainfer_qwen3")
284	    }
285	
286	    fn log(&self, record: &log::Record) {
287	        if self.enabled(record.metadata()) {
288	            eprintln!("[{}] {}", record.level(), record.args());
289	        }
290	    }
291	
292	    fn flush(&self) {}
293	}
294	
295	static TEST_LOGGER: TestLogger = TestLogger;
296	
297	pub(crate) fn init_capture_logging() {
298	    if std::env::var("PEGAINFER_TEST_LOG").is_ok() {
299	        let _ = log::set_logger(&TEST_LOGGER);
300	        log::set_max_level(log::LevelFilter::Debug);
301	    }
302	}
