1	//! HuggingFace-golden logits gate for Qwen3 (size-keyed: 4B, 14B, …) — the
2	//! hardware-independent replacement for the old text-snapshot e2e and digest.
3	//!
4	//! HuggingFace is the numerical golden truth. A bit-wise check (exact text or a
5	//! logprob hash) is fragile: bf16 GEMM kernels differ per GPU, so the low bits —
6	//! and any frozen snapshot — drift across hardware and false-positive on a
7	//! different card. Instead this gate asserts pegainfer lands within the *bf16
8	//! noise floor* of a stored HF reference, which every numerically-correct GPU
9	//! satisfies; only a real regression escapes the tolerance.
10	//!
11	//! The reference (`test_data/qwen3-{size}-hf-golden.safetensors`, produced once
12	//! by `tools/accuracy/dump_qwen3_hf_golden.py`) pins a set of fixed token
13	//! sequences and HF's top-K next-token logprobs at each position. We replay the
14	//! *same fixed sequences* through pegainfer by teacher-forcing — prefill the
15	//! prompt, then decode feeding the reference's own tail tokens — so every
16	//! position is compared against the identical-input HF distribution.
17	//! Teacher-forcing (vs free greedy) is what makes this stable: one argmax flip
18	//! can't send the two engines down diverging sequences.
19	//!
20	//! Assertions:
21	//!   * argmax — wherever HF has a clear winner (top-1 over top-2 margin exceeds a
22	//!     few bf16 ULP), pegainfer must pick the same token. Below that margin it is
23	//!     a genuine tie with no correct answer, so it is not enforced.
24	//!   * logprobs — on the head tokens, |pegainfer − HF| is bounded in the mean
25	//!     (catches uniform drift) and the p99 (catches a noisier subset). Both are
26	//!     coverage-stable; the single worst delta is reported but not asserted,
27	//!     because it grows with sample count (irreducible bf16 tail) while mean and
28	//!     p99 do not. A padding leak, KV mixing, or logit drift blows past them.
29	//!
30	//! The golden is replayed several ways, holding the *invariant the user cares
31	//! about* — stable logits across prompt / hardware / batch size:
32	//!   * bs=1 sequential (eager) — the tightest comparison; also rerun once to
33	//!     assert determinism (identical inputs ⇒ bit-identical logprobs).
34	//!   * batched eager — all sequences advance as one batch. Eager runs at the
35	//!     exact batch width (no padding), so this is the cross-request isolation
36	//!     check: requests of differing lengths share each kernel launch, and KV
37	//!     mixing or a per-request indexing bug corrupts a neighbour. It replaces the
38	//!     old exact batch==sequential check, which mistook the batched decode path's
39	//!     benign reduction-order noise (within tolerance here) for a bug — batch
40	//!     composition changes the reduction order and drifts logits ~1 ULP.
41	//!   * batched CUDA graph — the captured decode path pads the batch up to its
42	//!     bucket, so this is where padding-slot leaks (and graph pointer/buffer
43	//!     bugs) surface. Run the bucket straddles (9→16, 5→8) that maximise the
44	//!     padding-slot count. Only for a compiled GQA group; an uncompiled group
45	//!     (Qwen3-14B, group 5) reroutes decode eager and skips this pass.
46	//!
47	//! On a machine with ≥2 CUDA devices the eager replays additionally run under
48	//! TP=2 (`device_ordinals = [0, 1]`) against the same golden and tolerances —
49	//! sharding must not move logits beyond the single-GPU bf16 noise floor.
50	//!
51	//! Requires a CUDA GPU and Qwen3 weights of a keyed size; skips cleanly when the
52	//! model is absent (point `PEGAINFER_TEST_MODEL_PATH` at the weights to run it).
53	//! The TP pass skips on single-GPU hosts.
54	
55	use std::collections::HashMap;
56	use std::path::Path;
57	
58	use pegainfer_frontend::engine::TokenLogprob;
59	use pegainfer_frontend::sampler::SamplingParams;
60	use pegainfer_qwen3::runtime::DecodePlan;
61	use pegainfer_qwen3::runtime::DecodeStepItem;
62	use pegainfer_qwen3::runtime::PrefillPlan;
63	use pegainfer_qwen3::runtime::PrefillStepItem;
64	use pegainfer_qwen3::runtime::Qwen3Executor;
65	use pegainfer_qwen3::runtime::RequestId;
66	use safetensors::Dtype;
67	use safetensors::SafeTensors;
68	
69	const MODEL_PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../models/Qwen3-4B");
70	const GOLDEN_ENV: &str = "PEGAINFER_QWEN3_HF_GOLDEN";
71	
72	/// Ask the executor for as many logprobs as the golden stores so the top-K sets
73	/// overlap; the comparison only leans on the head, but a wider request makes the
74	/// argmax/tie reasoning robust.
75	const LOGPROBS: usize = 64;
76	/// KV reservation; prompts are short and the tail is `DECODE_TOKENS` long.
77	const MAX_OUTPUT_TOKENS: usize = 64;
78	
79	/// Max acceptable *regret*: how far below HF's own argmax (in HF's logprobs)
80	/// pegainfer's chosen token may sit. ~3 bf16 ULP at typical logit magnitudes —
81	/// genuine ties fall well under it; where HF has a clear winner the only token
82	/// within this regret is HF's argmax itself, so this still enforces exact
83	/// agreement there.
84	const MARGIN_TOL: f32 = 0.20;
85	/// Two coverage-stable, strict bounds on the head-delta distribution. They are
86	/// the right guards precisely because — unlike the single worst delta — they
87	/// barely move as coverage grows: widening the golden from 108 to 816 positions
88	/// left mean at 0.032 and p99 at 0.12, while the absolute max ran from 0.26 to
89	/// 0.44 (more samples ⇒ a fatter tail of irreducible bf16 rounding). So the max
90	/// is reported but *not* asserted — chasing it with a ceiling is a treadmill. A
91	/// wrong-*token* bug is caught structurally by the regret check; a systematic or
92	/// spread drift by these two.
93	///
94	/// `MEAN_TOL` 0.06 ≈ 2× the floor: a uniform logit drift of `d` nat shifts every
95	/// delta by ~`d`, so this trips on any systematic drift past ~0.03 nat (one bf16
96	/// ULP at logit magnitude ~8). That is the sensitivity the gate exists for.
97	const MEAN_TOL: f32 = 0.06;
98	/// `P99_TOL` 0.20 ≈ 1.6× the floor (0.12): catches *spread* inflation — a subset
99	/// of positions getting noisier — that the mean would average away. The single
100	/// worst token can't move it (it is one delta in thousands), so it stays put as
101	/// coverage grows, unlike the absolute max.
102	const P99_TOL: f32 = 0.20;
103	/// Head depth for the logprob tolerance check (tail tokens are inherently noisy).
104	const HEAD_K: usize = 8;
105	
106	/// Batch sizes for the batched passes, chosen against the CUDA-graph decode
107	/// buckets `[1, 2, 4, 8, 16, 20, ...]` (`BATCH_BUCKETS` in
108	/// `batch_decode_buffers.rs`). A
109	/// batch pads up to the next bucket, and padding-slot isolation is stressed
110	/// hardest just *past* a boundary, where almost a whole bucket is padding: 9
111	/// pads to 16 (7 pad slots) and 5 pads to 8 (3 pad slots). Both are well within
112	/// the golden's sequence count. The eager pass reuses the larger size purely as
113	/// a count of concurrent mixed-length requests (eager does not pad).
114	const BUCKET_STRADDLES: [usize; 2] = [9, 5];
115	
116	fn model_path_or_skip() -> Option<String> {
117	    match std::env::var("PEGAINFER_TEST_MODEL_PATH") {
118	        Ok(path) => Some(path),
119	        Err(_) if Path::new(MODEL_PATH).join("config.json").exists() => {
120	            Some(MODEL_PATH.to_string())
121	        }
122	        Err(_) => {
123	            eprintln!(
124	                "skipping qwen3 hf_golden_gate: {MODEL_PATH}/config.json is missing; set PEGAINFER_TEST_MODEL_PATH to run it"
125	            );
126	            None
127	        }
128	    }
129	}
130	
131	fn config_json(model_path: &str) -> serde_json::Value {
132	    let config_path = Path::new(model_path).join("config.json");
133	    let raw = std::fs::read_to_string(&config_path)
134	        .unwrap_or_else(|e| panic!("read {}: {e}", config_path.display()));
135	    serde_json::from_str(&raw).unwrap_or_else(|e| panic!("parse {}: {e}", config_path.display()))
136	}
137	
138	fn fixture_size_name(model_path: &str) -> Option<&'static str> {
139	    let v = config_json(model_path);
140	    let t = v.get("text_config").unwrap_or(&v);
141	    let hidden = t.get("hidden_size").and_then(serde_json::Value::as_u64);
142	    let layers = t
143	        .get("num_hidden_layers")
144	        .and_then(serde_json::Value::as_u64);
145	    let (Some(hidden), Some(layers)) = (hidden, layers) else {
146	        panic!("{model_path}/config.json has no hidden_size/num_hidden_layers");
147	    };
148	    match (hidden, layers) {
149	        (1024, 28) => Some("0.6b"),
150	        (2048, 28) => Some("1.7b"),
151	        (2560, 36) => Some("4b"),
152	        (4096, 36) => Some("8b"),
153	        (5120, 40) => Some("14b"),
154	        (5120, 64) => Some("32b"),
155	        _ => None,
156	    }
157	}
158	
159	const COMMITTED_FIXTURE_SIZES: &[&str] = &["0.6b", "1.7b", "4b", "8b", "14b", "32b"];
160	
161	fn default_fixture_path(size: &str) -> String {
162	    format!(
163	        "{}/../test_data/qwen3-{size}-hf-golden.safetensors",
164	        env!("CARGO_MANIFEST_DIR")
165	    )
166	}
167	
168	fn decode_group_compiled(model_path: &str) -> bool {
169	    let v = config_json(model_path);
170	    let t = v.get("text_config").unwrap_or(&v);
171	    let heads = t
172	        .get("num_attention_heads")
173	        .and_then(serde_json::Value::as_u64);
174	    let kv = t
175	        .get("num_key_value_heads")
176	        .and_then(serde_json::Value::as_u64);
177	    let (Some(heads), Some(kv)) = (heads, kv) else {
178	        panic!("{model_path}/config.json has no num_attention_heads/num_key_value_heads");
179	    };
180	    assert!(
181	        kv > 0 && heads % kv == 0,
182	        "invalid GQA head counts {heads}/{kv}"
183	    );
184	    pegainfer_core::ops::SUPPORTED_GQA_GROUP_SIZES.contains(&((heads / kv) as usize))
185	}
186	
187	fn as_i32(st: &SafeTensors, name: &str) -> (Vec<i32>, Vec<usize>) {
188	    let t = st
189	        .tensor(name)
190	        .unwrap_or_else(|e| panic!("golden missing {name}: {e}"));
191	    assert_eq!(t.dtype(), Dtype::I32, "{name} must be i32");
192	    let v = t
193	        .data()
194	        .as_chunks::<4>()
195	        .0
196	        .iter()
197	        .map(|b| i32::from_le_bytes(*b))
198	        .collect();
199	    (v, t.shape().to_vec())
200	}
201	
202	fn as_f32(st: &SafeTensors, name: &str) -> Vec<f32> {
203	    let t = st
204	        .tensor(name)
205	        .unwrap_or_else(|e| panic!("golden missing {name}: {e}"));
206	    assert_eq!(t.dtype(), Dtype::F32, "{name} must be f32");
207	    t.data()
208	        .as_chunks::<4>()
209	        .0
210	        .iter()
211	        .map(|b| f32::from_le_bytes(*b))
212	        .collect()
213	}
214	
215	fn top_logprobs(lp: Option<&TokenLogprob>) -> Vec<(u32, f32)> {
216	    lp.expect("logprobs requested but none returned")
217	        .top_logprobs
218	        .clone()
219	}
220	
221	#[derive(Default)]
222	struct Stats {
223	    positions: usize,
224	    argmax_violations: Vec<String>,
225	    head_deltas: Vec<f32>, // |pega - HF| logprob on the head tokens
226	    worst: Option<(f32, usize, usize, u32, f32, f32)>, // delta, seq, pos, token, pega, hf
227	    /// Prompt tokens served from the prefix cache, summed over all prefills.
228	    /// Zero when caching is disabled; the cached-replay passes assert it is not.
229	    cached_tokens: usize,
230	}
231	
232	/// Fold one position into `stats`. `hf` and `pega` are top-K `(token, logprob)`,
233	/// both sorted by descending logprob (rank 0 is the argmax).
234	fn check_position(
235	    stats: &mut Stats,
236	    seq: usize,
237	    pos: usize,
238	    pega: &[(u32, f32)],
239	    hf: &[(u32, f32)],
240	) {
241	    stats.positions += 1;
242	    let hf_top = hf[0].1;
243	    let pega_argmax = pega[0].0;
244	    let hf_map: HashMap<u32, f32> = hf.iter().copied().collect();
245	
246	    // pega's chosen token must be one HF also ranks near its own best. "Regret"
247	    // is how far below HF's argmax (in HF's own logprobs) pegainfer's pick sits.
248	    // A genuine bf16 tie differs by a ULP or two — small regret, fine. But a pick
249	    // HF scores clearly worse, or one absent from HF's top-K entirely (pegainfer
250	    // confidently wrong on a token HF does not even rank), is a real wrong-token
251	    // bug. This one rule subsumes "match HF where it is sure" *and* closes the
252	    // tie-band hole where a garbage argmax would otherwise escape every check.
253	    match hf_map.get(&pega_argmax) {
254	        None => stats.argmax_violations.push(format!(
255	            "seq {seq} pos {pos}: pegainfer's argmax {pega_argmax} is absent from HF's top-{} — confidently wrong on a token HF does not rank",
256	            hf.len()
257	        )),
258	        Some(&hlp) if hf_top - hlp > MARGIN_TOL => stats.argmax_violations.push(format!(
259	            "seq {seq} pos {pos}: pegainfer chose {pega_argmax}, which HF scores {:.4} nat below its own argmax (> {MARGIN_TOL} tie tolerance)",
260	            hf_top - hlp
261	        )),
262	        Some(_) => {}
263	    }
264	
265	    for &(token, plp) in pega.iter().take(HEAD_K) {
266	        if let Some(&hlp) = hf_map.get(&token) {
267	            let delta = (plp - hlp).abs();
268	            stats.head_deltas.push(delta);
269	            if stats.worst.is_none_or(|(w, ..)| delta > w) {
270	                stats.worst = Some((delta, seq, pos, token, plp, hlp));
271	            }
272	        }
273	    }
274	}
275	
276	/// The stored HF reference, parsed into owned vectors (the safetensors view
277	/// borrows the file bytes, so we copy out and let both drop).
278	struct Golden {
279	    prompt_tokens: Vec<i32>, // ragged, sliced by `prompt_lens`
280	    prompt_lens: Vec<i32>,   // [S]
281	    decode_tokens: Vec<i32>, // [S, D] flattened
282	    topk_ids: Vec<i32>,      // [S, D+1, K] flattened
283	    topk_lp: Vec<f32>,       // [S, D+1, K] flattened
284	    num_seqs: usize,
285	    decode_len: usize, // D
286	    positions: usize,  // D + 1
287	    k: usize,
288	}
289	
290	impl Golden {
291	    fn load_for(model_path: &str) -> Option<Golden> {
292	        let Some(size) = fixture_size_name(model_path) else {
293	            assert!(
294	                std::env::var(GOLDEN_ENV).is_err(),
295	                "{GOLDEN_ENV} is set but {model_path}/config.json geometry has no entry in the size table"
296	            );
297	            eprintln!(
298	                "skipping qwen3 hf_golden_gate: unrecognized model geometry in \
299	                 {model_path}/config.json; extend fixture_size_name to cover it"
300	            );
301	            return None;
302	        };
303	        let path = if let Ok(path) = std::env::var(GOLDEN_ENV) {
304	            path
305	        } else {
306	            let path = default_fixture_path(size);
307	            if !Path::new(&path).exists() {
308	                assert!(
309	                    !COMMITTED_FIXTURE_SIZES.contains(&size),
310	                    "committed golden fixture missing at {path}"
311	                );
312	                eprintln!(
313	                    "skipping qwen3 hf_golden_gate: no golden fixture for size {size} at {path}; \
314	                     generate one with tools/accuracy/dump_qwen3_hf_golden.py"
315	                );
316	                return None;
317	            }
318	            path
319	        };
320	        Some(Self::load_path(&path))
321	    }
322	
323	    fn load_path(path: &str) -> Golden {
324	        let bytes = std::fs::read(path).unwrap_or_else(|e| panic!("read {path}: {e}"));
325	        let st = SafeTensors::deserialize(&bytes).expect("parse golden safetensors");
326	        let (prompt_tokens, _) = as_i32(&st, "prompt_tokens");
327	        let (prompt_lens, _) = as_i32(&st, "prompt_lens");
328	        let (decode_tokens, dshape) = as_i32(&st, "decode_tokens");
329	        let (topk_ids, ishape) = as_i32(&st, "topk_ids");
330	        let topk_lp = as_f32(&st, "topk_logprobs");
331	        let num_seqs = prompt_lens.len();
332	        let decode_len = dshape[1];
333	        let positions = ishape[1];
334	        let k = ishape[2];
335	        assert_eq!(
336	            positions,
337	            decode_len + 1,
338	            "positions must be decode_len + 1"
339	        );
340	        Golden {
341	            prompt_tokens,
342	            prompt_lens,
343	            decode_tokens,
344	            topk_ids,
345	            topk_lp,
346	            num_seqs,
347	            decode_len,
348	            positions,
349	            k,
350	        }
351	    }
352	
353	    fn prompt(&self, seq: usize) -> Vec<u32> {
354	        let off: usize = self.prompt_lens[..seq].iter().map(|&l| l as usize).sum();
355	        let len = self.prompt_lens[seq] as usize;
356	        self.prompt_tokens[off..off + len]
357	            .iter()
358	            .map(|&t| t as u32)
359	            .collect()
360	    }
361	
362	    fn decode(&self, seq: usize, step: usize) -> u32 {
363	        self.decode_tokens[seq * self.decode_len + step] as u32
364	    }
365	
366	    fn topk(&self, seq: usize, pos: usize) -> Vec<(u32, f32)> {
367	        let base = (seq * self.positions + pos) * self.k;
368	        (0..self.k)
369	            .map(|j| (self.topk_ids[base + j] as u32, self.topk_lp[base + j]))
370	            .collect()
371	    }
372	}
373	
374	fn prefill_item(id: RequestId, prompt: Vec<u32>) -> PrefillStepItem {
375	    PrefillStepItem::new(
376	        id,
377	        prompt,
378	        MAX_OUTPUT_TOKENS,
379	        SamplingParams::default(),
380	        Some(LOGPROBS),
381	        None,
382	    )
383	}
384	
385	fn decode_item(id: RequestId, fed: u32) -> DecodeStepItem {
386	    DecodeStepItem::new(id, fed, SamplingParams::default(), Some(LOGPROBS))
387	}
388	
389	/// Teacher-force the golden sequences `seqs` through `ex` and fold every
390	/// position into a [`Stats`]. `batched = false` runs each sequence alone (bs=1,
391	/// the tightest comparison); `batched = true` advances them all as one batch.
392	/// Restricting `seqs` lets a caller hit a specific CUDA-graph bucket (e.g. 5
393	/// seqs → bucket 8) so more than one real/pad ratio is exercised. The returned
394	/// vector is pegainfer's own top-1 logprob at each evaluated position — a
395	/// fingerprint two identical runs must reproduce bit-for-bit (determinism).
396	fn run(g: &Golden, ex: &mut Qwen3Executor, seqs: &[usize], batched: bool) -> (Stats, Vec<f32>) {
397	    let mut stats = Stats::default();
398	    let mut fingerprint = Vec::new();
399	    let mut fold = |stats: &mut Stats, seq, pos, pega: &[(u32, f32)]| {
400	        fingerprint.push(pega[0].1);
401	        check_position(stats, seq, pos, pega, &g.topk(seq, pos));
402	    };
403	
404	    if batched {
405	        let ids: Vec<RequestId> = (0..seqs.len())
406	            .map(|i| RequestId::new(1000 + i as u64))
407	            .collect();
408	        let items: Vec<PrefillStepItem> = seqs
409	            .iter()
410	            .zip(&ids)
411	            .map(|(&s, &id)| prefill_item(id, g.prompt(s)))
412	            .collect();
413	        let pr = ex
414	            .execute_prefill(PrefillPlan {
415	                sample_seed: 0,
416	                requests: &items,
417	            })
418	            .expect("prefill");
419	        for (i, &s) in seqs.iter().enumerate() {
420	            stats.cached_tokens += pr.requests[i].cached_tokens.unwrap_or(0);
421	            fold(
422	                &mut stats,
423	                s,
424	                0,
425	                &top_logprobs(pr.requests[i].first_token_logprob.as_ref()),
426	            );
427	        }
428	        for step in 0..g.decode_len {
429	            let items: Vec<DecodeStepItem> = seqs
430	                .iter()
431	                .zip(&ids)
432	                .map(|(&s, &id)| decode_item(id, g.decode(s, step)))
433	                .collect();
434	            let dr = ex
435	                .execute_decode(DecodePlan {
436	                    sample_seed: 0,
437	                    requests: &items,
438	                })
439	                .expect("decode");
440	            for (i, &s) in seqs.iter().enumerate() {
441	                fold(
442	                    &mut stats,
443	                    s,
444	                    step + 1,
445	                    &top_logprobs(dr.requests[i].logprob.as_ref()),
446	                );
447	            }
448	        }
449	        for &id in &ids {
450	            ex.drop_request(id).expect("drop request");
451	        }
452	    } else {
453	        for &seq in seqs {
454	            let id = RequestId::new(seq as u64);
455	            let pr = ex
456	                .execute_prefill(PrefillPlan {
457	                    sample_seed: 0,
458	                    requests: &[prefill_item(id, g.prompt(seq))],
459	                })
460	                .expect("prefill");
461	            stats.cached_tokens += pr.requests[0].cached_tokens.unwrap_or(0);
462	            fold(
463	                &mut stats,
464	                seq,
465	                0,
466	                &top_logprobs(pr.requests[0].first_token_logprob.as_ref()),
467	            );
468	            for step in 0..g.decode_len {
469	                let dr = ex
470	                    .execute_decode(DecodePlan {
471	                        sample_seed: 0,
472	                        requests: &[decode_item(id, g.decode(seq, step))],
473	                    })
474	                    .expect("decode");
475	                fold(
476	                    &mut stats,
477	                    seq,
478	                    step + 1,
479	                    &top_logprobs(dr.requests[0].logprob.as_ref()),
480	                );
481	            }
482	            ex.drop_request(id).expect("drop request");
483	        }
484	    }
485	    (stats, fingerprint)
486	}
487	
488	/// `(mean, p50, p99, max)` of a delta slice.
489	fn dist(deltas: &[f32]) -> (f32, f32, f32, f32) {
490	    let mut s = deltas.to_vec();
491	    s.sort_by(|a, b| a.partial_cmp(b).unwrap());
492	    let pct = |q: f64| s[((s.len() as f64 * q) as usize).min(s.len() - 1)];
493	    (
494	        s.iter().sum::<f32>() / s.len() as f32,
495	        pct(0.50),
496	        pct(0.99),
497	        *s.last().unwrap(),
498	    )
499	}
500	
501	fn report_and_assert(label: &str, stats: &Stats) {
502	    // Every position contributes at least its argmax token to `head_deltas` (the
503	    // regret check guarantees pega's argmax is in HF's top-K), so a count below
504	    // one-per-position means the top-K overlap collapsed and the mean is being
505	    // computed over too few samples to trust — fail loudly rather than pass on a
506	    // shrunken sample. (Also guards `dist` against an empty slice.)
507	    assert!(
508	        stats.head_deltas.len() >= stats.positions,
509	        "[{label}] only {} head deltas over {} positions — top-K overlap with HF collapsed",
510	        stats.head_deltas.len(),
511	        stats.positions
512	    );
513	    let (mean, p50, p99, max) = dist(&stats.head_deltas);
514	    eprintln!(
515	        "hf_golden_gate [{label}]: {} positions, {} head deltas — \
516	         mean {mean:.4} p50 {p50:.4} p99 {p99:.4} max {max:.4}",
517	        stats.positions,
518	        stats.head_deltas.len(),
519	    );
520	    if let Some((d, s, p, tok, plp, hlp)) = stats.worst {
521	        eprintln!(
522	            "hf_golden_gate [{label}]: worst head delta {d:.4} @ seq {s} pos {p} token {tok} (pega {plp:.4}, HF {hlp:.4})"
523	        );
524	    }
525	
526	    assert!(
527	        stats.argmax_violations.is_empty(),
528	        "[{label}] pegainfer picked a token HF does not rank near its best:\n  {}",
529	        stats.argmax_violations.join("\n  ")
530	    );
531	    assert!(
532	        mean <= MEAN_TOL,
533	        "[{label}] mean head logprob delta {mean:.4} > {MEAN_TOL} — logits drifted uniformly across the distribution (see above)"
534	    );
535	    assert!(
536	        p99 <= P99_TOL,
537	        "[{label}] p99 head logprob delta {p99:.4} > {P99_TOL} — a subset of positions got noisier than bf16 rounding (see above)"
538	    );
539	    let _ = max; // reported above, but not asserted: the worst single delta grows with coverage
540	}
541	
542	/// Number of visible CUDA devices; 0 when the driver cannot be queried.
543	fn cuda_device_count() -> usize {
544	    cudarc::driver::CudaContext::device_count().map_or(0, |n| n.max(0) as usize)
545	}
546	
547	/// The eager replay suite — bs=1 sequential (plus the bit-identical
548	/// determinism rerun), batched eager isolation, and the prefix-cached replays
549	/// — over a given device set, with `label` prefixing every report line.
550	fn run_eager_suite(golden: &Golden, model_path: &str, devices: &[usize], label: &str) {
551	    let all: Vec<usize> = (0..golden.num_seqs).collect();
552	    let mut ex = Qwen3Executor::from_runtime(model_path, false, devices)
553	        .unwrap_or_else(|e| panic!("build eager executor on {devices:?}: {e:#}"));
554	    // The determinism and isolation passes need bit-replayable prefill: a
555	    // prefix-cache hit shrinks the prefill GEMM to the uncached suffix,
556	    // which drifts logits by bf16 ULPs. Caching gets its own pass below.
557	    ex.set_prefix_cache_enabled(false);
558	
559	    // bs=1 sequential over *every* golden sequence — this is the breadth of
560	    // the prompt/length coverage (one request's KV at a time, so it scales to
561	    // long prompts cheaply). Also the determinism anchor: a second identical
562	    // run must reproduce every logprob bit-for-bit. A nondeterministic kernel
563	    // or uninitialised decode scratch would not.
564	    let (stats, fp1) = run(golden, &mut ex, &all, false);
565	    report_and_assert(&format!("{label}sequential bs=1 eager"), &stats);
566	    let (_, fp2) = run(golden, &mut ex, &all, false);
567	    assert_eq!(
568	        fp1, fp2,
569	        "{label}sequential bs=1 eager: identical inputs must reproduce identical logprobs"
570	    );
571	
572	    // A batch advanced together (eager runs at the exact width — no padding).
573	    // This is the cross-request isolation check: requests of differing
574	    // lengths/page layouts share each kernel launch, so KV mixing or a
575	    // per-request indexing bug corrupts a neighbour's logits. It replaces the
576	    // old exact batch==sequential check, which mistook the batched decode
577	    // path's benign reduction-order noise (within tolerance here) for a bug.
578	    // Breadth is the bs=1 pass's job; this just needs enough concurrent reqs.
579	    let n = BUCKET_STRADDLES[0];
580	    let (batched, _) = run(golden, &mut ex, &all[..n], true);
581	    report_and_assert(&format!("{label}batched eager ({n}, no pad)"), &batched);
582	
583	    // Prefix-cached replay. Matching-disabled requests intentionally reset
584	    // their completed blocks, so first seed under enabled retention and then
585	    // rerun warm: prefill skips the cached prefix and attention spans cached
586	    // KV + recomputed suffix (kv_len > q_len). Same HF tolerances — a wrong
587	    // RoPE offset, mask, or stale page would blow far past them.
588	    ex.set_prefix_cache_enabled(true);
589	    let _ = run(golden, &mut ex, &all, false);
590	    let (cached, _) = run(golden, &mut ex, &all, false);
591	    assert!(
592	        cached.cached_tokens > 0,
593	        "{label}cached replay matched no prefix blocks — the cache path was not exercised"
594	    );
595	    report_and_assert(
596	        &format!("{label}sequential bs=1 eager cached replay"),
597	        &cached,
598	    );
599	    let (cached_batched, _) = run(golden, &mut ex, &all[..n], true);
600	    report_and_assert(
601	        &format!("{label}batched eager cached replay ({n})"),
602	        &cached_batched,
603	    );
604	}
605	
606	#[test]
607	fn pega_logprobs_match_hf_golden_within_bf16_tolerance() {
608	    let Some(model_path) = model_path_or_skip() else {
609	        return;
610	    };
611	    let Some(golden) = Golden::load_for(&model_path) else {
612	        return;
613	    };
614	    let all: Vec<usize> = (0..golden.num_seqs).collect();
615	
616	    // Debug knob: skip the single-GPU passes and run only the TP=2 suite.
617	    // The full gate builds TP executors after single-GPU executors in the
618	    // same process; running with this set isolates the TP pass from any
619	    // state they leave behind.
620	    if std::env::var("PEGAINFER_GOLDEN_TP_ONLY").is_ok() {
621	        let gpus = cuda_device_count();
622	        assert!(
623	            gpus >= 2,
624	            "PEGAINFER_GOLDEN_TP_ONLY needs >=2 GPUs, have {gpus}"
625	        );
626	        run_eager_suite(&golden, &model_path, &[0, 1], "tp2 ");
627	        return;
628	    }
629	
630	    // Each executor owns its GPU memory; scope them so only one model is
631	    // resident at a time (drop frees it before the next load). Everything
632	    // stays in one #[test] for the same reason: two parallel tests would both
633	    // budget 85% of free VRAM for KV.
634	    run_eager_suite(&golden, &model_path, &[0], "");
635	
636	    // CUDA-graph decode is captured per bucket and pads the batch up to it, so
637	    // this path is where padding-slot leaks (and graph pointer/buffer bugs)
638	    // surface. Run the bucket straddles, which maximise the padding-slot count.
639	    if decode_group_compiled(&model_path) {
640	        let mut ex = Qwen3Executor::from_runtime(&model_path, true, &[0])
641	            .expect("build cuda-graph executor");
642	        ex.set_prefix_cache_enabled(false);
643	        for n in BUCKET_STRADDLES {
644	            let (batched, _) = run(&golden, &mut ex, &all[..n], true);
645	            report_and_assert(&format!("batched cuda-graph ({n} padded)"), &batched);
646	        }
647	
648	        // Graph decode over shared cached pages: the captured graph reads page
649	        // tables that now point at blocks written by earlier requests.
650	        ex.set_prefix_cache_enabled(true);
651	        let n = BUCKET_STRADDLES[1];
652	        let _ = run(&golden, &mut ex, &all[..n], true);
653	        let (cached, _) = run(&golden, &mut ex, &all[..n], true);
654	        assert!(
655	            cached.cached_tokens > 0,
656	            "cuda-graph cached replay matched no prefix blocks"
657	        );
658	        report_and_assert(&format!("batched cuda-graph cached replay ({n})"), &cached);
659	    } else {
660	        eprintln!(
661	            "hf_golden_gate: skipping CUDA-graph passes for {model_path} (uncompiled GQA group, reroutes to eager)"
662	        );
663	    }
664	
665	    // TP=2: the same eager suite sharded over two GPUs. Same golden, same
666	    // tolerances — a reduction-order, shard-offset, or all-reduce bug drifts
667	    // logits far past the bf16 noise floor.
668	    let gpus = cuda_device_count();
669	    if gpus < 2 {
670	        eprintln!("skipping hf_golden_gate TP=2 pass: {gpus} CUDA device(s) visible, need 2");
671	        return;
672	    }
673	    run_eager_suite(&golden, &model_path, &[0, 1], "tp2 ");
674	
675	    // TP=2, graph on: replay the pre-captured decode graphs against the same
676	    // golden, so a bad shard, pointer, or collective in a capture drifts logits.
677	    if decode_group_compiled(&model_path) {
678	        let mut ex = Qwen3Executor::from_runtime(&model_path, true, &[0, 1])
679	            .expect("build cuda-graph TP executor");
680	        ex.set_prefix_cache_enabled(false);
681	        for n in BUCKET_STRADDLES {
682	            let (batched, _) = run(&golden, &mut ex, &all[..n], true);
683	            report_and_assert(&format!("tp2 batched cuda-graph ({n} padded)"), &batched);
684	        }
685	    }
686	}
